 def setup(width):
  c=b.new_context(viewport={'width':width,'height':844},reduced_motion='reduce');c.add_init_script("window.syntheticAudioStarts=0;const ActualAudioContext=window.AudioContext;if(ActualAudioContext)window.AudioContext=new Proxy(ActualAudioContext,{construct(target,args){window.syntheticAudioStarts++;return Reflect.construct(target,args)}})");a=c.new_page();a.on('pageerror',lambda e:errors.append(str(e)));a.goto(args.url+'/start');a.evaluate("localStorage.setItem('haven_onboarded','1')");return c,a
