 def block(target,key,mode='silent'):
  if isinstance(target,Locator):
   target.evaluate("(frame,[key,mode])=>{const w=frame.contentWindow;w.originalSet=w.Storage.prototype.setItem;w.Storage.prototype.setItem=function(k,v){if(k===key){if(mode==='throw')throw new Error('Synthetic quota');return;}return w.originalSet.call(this,k,v)};}",[key,mode]);return
  target.evaluate("([key,mode])=>{window.originalSet=Storage.prototype.setItem;Storage.prototype.setItem=function(k,v){if(k===key){if(mode==='throw')throw new Error('Synthetic quota');return;}return window.originalSet.call(this,k,v)};}",[key,mode])
 def unblock(target):
  if isinstance(target,Locator):target.evaluate('frame=>{frame.contentWindow.Storage.prototype.setItem=frame.contentWindow.originalSet;}')
  else:target.evaluate('()=>{Storage.prototype.setItem=window.originalSet;}')
